def verify_response(result: GetAddressUuuid, batch: list[str]) -> bool:
    for res in result.addresses.objects:
        current = res.current
        if current is None or current.ituser_response is None or current.ituser_response.current is None:
            return False
        if str(current.ituser_response.current.user_key) not in batch:
            return False
    return True

async def process_batch(client: GraphQLClient, batch: list[str]) -> GetAddressUuuid:
    async with concurrent_tasks:
        filter = AddressFilter(ituser=ITUserFilter(user_keys=batch))
        # print(f"Processing batch: {batch}")
        response = await client.get_address_uuuid(filter)
        verified = verify_response(response, batch)

        return response


