def check_address(result: GetAddressUuuid):
    if result is not None:
        list_of_addresses_to_delete = get_list_of_addresses_to_delete()
        list_of_addresses = result.addresses.objects
        for obj in list_of_addresses:
            current = obj.current
            if current is not None and str(current.uuid) in list_of_addresses_to_delete:
                print(f"Address {current.uuid} is set for deletion")
                ad_account_current = current.ituser_response
                if ad_account_current is not None and ad_account_current.current is not None:
                    ad_account = ad_account_current.current.user_key
                    print(f"AD details: {ad_account}")
                else:
                    print("AD details: ")

        # objects = response["data"]["addresses"]["objects"]
