        #             print(f"AD details: {ad_account}")

async def main(csv_file: str):
    ad_data = Utils().read_ad_csv(csv_file)
    list_of_usernames = Utils().get_usernames(ad_data)

    gql_client = Utils().get_graphql_client()
    tasks = []

    # await process_user(gql_client, list_of_usernames)
    # for i in range(0, len(list_of_usernames), batch_size):
    for i in range(0, 4, batch_size):
        batch = list_of_usernames[i:i + batch_size]
        tasks.append(process_batch(gql_client, batch))

    results: list[GetAddressUuuid | BaseException] = await asyncio.gather(*tasks, return_exceptions=True)
    for result in results:
        if isinstance(result, BaseException):
            print(f"Error: {result}")
            continue
        check_address(result)

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Verify address for users")
    parser.add_argument("csv_file", help="Path to the CSV file containing user data")
    args = parser.parse_args()
    asyncio.run(main(args.csv_file))
